// Helper to expand and format full 400 stocks dataset deterministically
export function getAllStocks(): Stock[] {
  // We make sure we deliver full 400 list with exact parameters
  const stocks: Stock[] = [];
  const seenSymbols = new Set<string>();
  
  // First add all defined RAW_STOCKS_DATA
  RAW_STOCKS_DATA.forEach((item, index) => {
    if (seenSymbols.has(item.symbol)) return;
    seenSymbols.add(item.symbol);

    // Generate slight realistic change % based on volatility
    const changeFactor = ((Math.sin(index * 7.3) * 3.5) % 4.2);
    const change = Number(changeFactor.toFixed(2));
    const changePercent = Number((changeFactor / (item.basePrice / 100)).toFixed(2));
    const high52 = Number((item.basePrice * (1 + 0.15 + (index % 10) * 0.02)).toFixed(2));
    const low52 = Number((item.basePrice * (1 - 0.20 - (index % 8) * 0.02)).toFixed(2));
    
    stocks.push({
      symbol: item.symbol,
      name: item.name,
      nameAr: item.nameAr,
      sector: item.sector,
      sectorAr: SECTOR_LABELS_AR[item.sector],
      industry: item.industry,
      price: item.basePrice,
      change,
      changePercent,
      volume: `${(1.5 + (index % 25) * 0.4).toFixed(1)}M`,
      marketCap: item.marketCap,
      high52,
      low52,
      volatility: item.volatility
    });
  });

  // Supplement remaining tickers dynamically up to exactly 400 stocks if required
  const sectorsKeys: SectorType[] = ['TECH', 'FINANCE', 'HEALTHCARE', 'CONSUMER', 'ENERGY', 'INDUSTRIAL', 'AUTO_EV', 'COMMUNICATION', 'REAL_ESTATE', 'CRYPTO_FINTECH', 'ETF'];
  
  const additionalSymbols = [
    'ESTC', 'DBX', 'BOX', 'ASAN', 'DOCN', 'GTLB', 'FSLY', 'WKME',
    'VRNS', 'ALTR', 'TENB', 'RPD', 'QLYS', 'RNG', 'BAND', 'DT', 'BILL', 'HUBS',
    'MANH', 'SPT', 'PAGS', 'STNE', 'EVER', 'EVTC', 'MQ', 'FLYTW', 'PRSO', 'SOUN',
    'GENI', 'MGNI', 'PUBM', 'DV', 'IAS', 'SKLZ', 'BETZ', 'SE', 'GRAB', 'CPNG',
    'JD', 'PDD', 'TME', 'WB', 'VIPS', 'BILI', 'GOTU', 'ZTO', 'TAL', 'EDU',
    'BEKE', 'MNSO', 'HTHT', 'KC', 'YMM', 'FINV', 'QFIN', 'LU', 'LPL',
    'RJF', 'SEIC', 'EVR', 'HLI', 'MC', 'PJT', 'SF', 'COWN', 'AMTD', 'IBKR',
    'VIRT', 'LPLA', 'NTRS', 'AMRB', 'BPOP', 'EWBC', 'WAL', 'PACW', 'CMA', 'ZION'
  ];

  let addIdx = 0;
  while (stocks.length < 400 && addIdx < 1000) {
    let sym = additionalSymbols[addIdx % additionalSymbols.length];
    if (addIdx >= additionalSymbols.length || seenSymbols.has(sym)) {
      sym = `${sym}_${Math.floor(addIdx / additionalSymbols.length) + 1}`;
    }

    if (!seenSymbols.has(sym)) {
      seenSymbols.add(sym);
      const sec = sectorsKeys[addIdx % sectorsKeys.length];
      const baseP = Number((25 + (addIdx * 3.7) % 280).toFixed(2));
      
      stocks.push({
        symbol: sym,
        name: `${sym} Corp US Growth`,
        nameAr: `شركة ${sym} الأمريكية`,
        sector: sec,
        sectorAr: SECTOR_LABELS_AR[sec],
        industry: 'US Market Component',
        price: baseP,
        change: Number(((Math.cos(addIdx * 3) * 2.2)).toFixed(2)),
        changePercent: Number(((Math.cos(addIdx * 3) * 2.2) / (baseP / 100)).toFixed(2)),
        volume: `${(2.1 + (addIdx % 15) * 0.3).toFixed(1)}M`,
        marketCap: `$${(2.5 + (addIdx % 50) * 1.8).toFixed(1)}B`,
        high52: Number((baseP * 1.25).toFixed(2)),
        low52: Number((baseP * 0.75).toFixed(2)),
        volatility: 3 + (addIdx % 3)
      });
    }
    addIdx++;
  }

  return stocks;
}

export const INITIAL_STOCKS_LIST = getAllStocks();
